test('SM4: parse fallback and deployment file ceilings refuse typed', async () => {
  for (const [taskId, resolver, expected] of [
   120|    ['sm-fallback', { maxFileBytes: 4096, identity: () => ({ tool: 'fake' }), resolve: async () => ({ status: 'parse_fallback' }) }, 'structured_parse_fallback'],
