  const root = repo();
  const resolver = { maxFileBytes: 4096, identity: () => ({ tool: 'fake-mergiraf', version: 'test' }), resolve: async ({ absolutePath }) => { writeFileSync(absolutePath, 'export const values = ;\n'); return { status: 'resolved' }; } };
